def image_reader_dict(
    data: dict | Sequence[dict],
    keys: str | Iterable[str],
    lazy: bool = False,
    transforms: Callable | list[Callable] | None = None,
    loader: Callable | None = None,
    channels: str = "CZYX",
    ind_dict: dict | None = None,
    npz_key: str | None = None,
    dtype=torch.float32,                                
    squeeze: bool = False,                              
    stack_axis: str = "C",                              

):
    """
    Load images from paths stored inside dictionary keys.

    Supports:
        - single dictionary input
        - sequence of dictionaries
        - eager or lazy execution

    The specified keys are replaced with loaded/preprocessed MetaTensor
    objects while preserving the remaining dictionary structure.

    Args:
        data:
            Input dictionary or sequence of dictionaries.
        keys:
            Key or iterable of keys containing file paths.
        lazy:
            Whether to lazily stream sequence inputs.
        transforms:
            Optional dictionary-based transforms.
        loader:
            Optional custom loader.
        channels:
            Channel layout string.
        ind_dict:
            Optional indexing dictionary.
        npz_key:
            Optional NPZ key.

    Returns:
        dict | list[dict] | Iterable[dict]:
            Loaded dictionary sample(s).
    """

    def _load(obj):
        return _load_and_preprocess_dict(
            obj=obj,
            keys=keys,
            transforms=transforms,
            loader=loader,
            channels=channels,
            ind_dict=ind_dict,
            npz_key=npz_key,
        )

    def _iter_multi():
        if lazy:
            return _multi_sequence_stream_dict(
                objs=data,
                keys=keys,
                transforms=transforms,
                loader=loader,
                channels=channels,
                ind_dict=ind_dict,
                npz_key=npz_key,
            )

        return [_load(obj) for obj in data]

    
    if not keys: 
        return data
    
    if isinstance(keys, str):
        keys = [keys]

    is_multi = (
        isinstance(data, Sequence)
        and not isinstance(data, dict)
    )

    # -------------------------------------------------
    # MULTI CASE
    # -------------------------------------------------
    if is_multi:
        d_list = _iter_multi()
        out = d_list[0]

        for key in keys:
            metatensors = [d[key] for d in d_list]
            metatensor = _stack(metatensors, stack_axis=stack_axis, channels=channels, dtype=dtype, squeeze=squeeze)
            metatensor.meta.update(_meta_from_layout(metatensor.shape, metatensor.meta['layout']))

            out[key] = metatensor


        return out

    # -------------------------------------------------
    # SINGLE CASE
    # -------------------------------------------------
    out = _load(data)

    for key in keys:
        out[key].meta.update(_meta_from_layout(out[key].shape, channels))

    return out

